<?php
// AI generated by pi coding agent, v1.0
declare(strict_types=1);

/**
 * GET api/series.php
 *
 * Aggregated time series for the chart.
 *
 * Parameters:
 *   fields  comma separated subset of temp_inside,hum_inside,temp_outside,hum_outside
 *           (default: temp_inside,temp_outside)
 *   bucket  5m | 1h | 1d  (default: 1h)
 *   hours   window size in hours, counted back from now (optional)
 *   from    YYYY-MM-DD or YYYY-MM-DD HH:MM:SS (optional)
 *   to      YYYY-MM-DD or YYYY-MM-DD HH:MM:SS (optional)
 *
 * Without any of hours/from/to the complete history is returned.
 *
 * `t` is a UNIX timestamp in seconds; the frontend feeds it straight into the
 * uPlot time axis. The aggregation is done by SQL (AVG per bucket), which also
 * averages away rows written twice by an importer re-run.
 */

require __DIR__ . '/bootstrap.php';

$fields = query_fields('temp_inside,temp_outside');
$bucket = query_enum('bucket', PI_SENSOR_BUCKETS, '1h');

// ---------------------------------------------------------------------------
// Time window
// ---------------------------------------------------------------------------

$hours = null;
if (isset($_GET['hours']) && $_GET['hours'] !== '') {
    $hours = query_int('hours', 24, 1, PI_SENSOR_MAX_HOURS);
}

$from = parse_datetime_param('from');
$to = parse_datetime_param('to');

// A raw 5-minute resolution over the whole history is never wanted (and would
// return tens of thousands of points): require an explicit window.
if ($bucket === '5m' && $from === null && $to === null && $hours === null) {
    json_error("Auflösung '5m' benötigt die Parameter 'hours', 'from' oder 'to'");
}

$conditions = [];
$parameters = [];

if ($from !== null && $to !== null) {
    $conditions[] = 'measured_at BETWEEN ? AND ?';
    $parameters[] = $from;
    $parameters[] = $to;
} elseif ($from !== null) {
    $conditions[] = 'measured_at >= ?';
    $parameters[] = $from;
} elseif ($to !== null) {
    $conditions[] = 'measured_at <= ?';
    $parameters[] = $to;
} elseif ($hours !== null) {
    $conditions[] = 'measured_at >= ?';
    // Reference clock comes from the database, see db_since().
    $parameters[] = db_since($hours);
}

// ---------------------------------------------------------------------------
// Bucketing
// ---------------------------------------------------------------------------

// Only whitelisted literals end up in the SQL string below.
$bucketExpression = match ($bucket) {
    '5m' => 'measured_at',
    '1h' => "DATE_FORMAT(measured_at, '%Y-%m-%d %H:00:00')",
    '1d' => 'DATE(measured_at)',
};

$selected = ['UNIX_TIMESTAMP(' . $bucketExpression . ') AS t'];
foreach ($fields as $field) {
    $selected[] = "AVG({$field}) AS {$field}";
}

$sql = 'SELECT ' . implode(",\n           ", $selected) . '
          FROM measurements';
if ($conditions !== []) {
    $sql .= "\n         WHERE " . implode(' AND ', $conditions);
}
$sql .= "\n         GROUP BY " . $bucketExpression
    . "\n         ORDER BY " . $bucketExpression;

try {
    $statement = db()->prepare($sql);
    foreach ($parameters as $index => $value) {
        $statement->bindValue($index + 1, $value, PDO::PARAM_STR);
    }
    $statement->execute();
    $rows = $statement->fetchAll();
} catch (PDOException $e) {
    error_log('pi_sensor: series query failed: ' . $e->getMessage());
    json_error('Abfrage fehlgeschlagen', 503);
}

// ---------------------------------------------------------------------------
// Response
// ---------------------------------------------------------------------------

$points = [];
foreach ($rows as $row) {
    $point = ['t' => (int) $row['t']];
    foreach ($fields as $field) {
        $point[$field] = round_or_null($row[$field] ?? null);
    }
    $points[] = $point;
}

json_out([
    'fields' => $fields,
    'bucket' => $bucket,
    'points' => $points,
], 200, 60);
// End of AI generated by pi coding agent, v1.0
